SELECT CASE WHEN COALESCE(created_by, '') LIKE 'import-excel-2026%' THEN 'import-excel-2026' ELSE COALESCE(NULLIF(TRIM(created_by), ''), '(created_by kosong)') END AS sumber, category_id, COUNT(*) AS jumlah, COALESCE(SUM(amount), 0) AS total FROM finance_entries WHERE kind = 'income' AND entry_date >= '2026-09-01' AND entry_date < '2026-10-01' GROUP BY sumber, category_id ORDER BY total DESC;
